-- DeliTools foundation schema: operator settings, API keys, audit records and operational events.
-- Identifiers are UUID v7 values generated by the service. This schema never stores inputs,
-- JSON schemas, results or raw credentials. Migrations are forward-only; recovery is fix-forward.

-- created_at is the immutable origin of the 30-day retention clock. A state change, retry or any
-- other update must never move it, so the database refuses to change it.
CREATE FUNCTION forbid_created_at_change() RETURNS trigger AS $$
BEGIN
    IF NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'created_at is immutable' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- One row. Seeded from the environment exactly once; afterwards only UpdateSettings changes it.
CREATE TABLE settings (
    singleton                  boolean PRIMARY KEY DEFAULT true CHECK (singleton),
    max_input_bytes            integer NOT NULL CHECK (max_input_bytes > 0),
    max_translation_items      integer NOT NULL CHECK (max_translation_items > 0),
    execution_timeout_seconds  integer NOT NULL CHECK (execution_timeout_seconds > 0),
    tenant_requests_per_minute integer NOT NULL CHECK (tenant_requests_per_minute > 0),
    tenant_concurrency         integer NOT NULL CHECK (tenant_concurrency > 0),
    -- Zero is a valid explicit retry count.
    max_ai_retries             integer NOT NULL CHECK (max_ai_retries >= 0),
    price_sync_seconds         integer NOT NULL CHECK (price_sync_seconds > 0),
    delivery_retry_seconds     integer NOT NULL CHECK (delivery_retry_seconds > 0),
    max_backoff_seconds        integer NOT NULL CHECK (max_backoff_seconds >= delivery_retry_seconds),
    alert_backlog              integer NOT NULL CHECK (alert_backlog > 0),
    alert_expiry_seconds       integer NOT NULL CHECK (alert_expiry_seconds > 0),
    translation_models         jsonb NOT NULL CHECK (jsonb_typeof(translation_models) = 'array'),
    version                    bigint NOT NULL DEFAULT 1,
    created_at                 timestamptz NOT NULL,
    updated_at                 timestamptz NOT NULL
);
CREATE TRIGGER settings_created_at BEFORE UPDATE ON settings
    FOR EACH ROW EXECUTE FUNCTION forbid_created_at_change();

-- API keys belong to a tenant. kind: 1 personal, 2 service. capabilities: 1 translator, 2 extractor.
-- Keys do not expire with request records and are never deleted by retention.
CREATE TABLE api_keys (
    id           uuid PRIMARY KEY,
    tenant_id    uuid NOT NULL,
    -- Personal keys: the owning user. Service keys: the issuing user, kept for attribution only.
    user_id      uuid NOT NULL,
    kind         smallint NOT NULL CHECK (kind IN (1, 2)),
    capabilities smallint[] NOT NULL
        CHECK (cardinality(capabilities) BETWEEN 1 AND 2 AND capabilities <@ ARRAY[1, 2]::smallint[]),
    -- Domain-separated SHA-256 of the secret. The secret itself is never stored.
    secret_hash  bytea NOT NULL CHECK (octet_length(secret_hash) = 32),
    created_at   timestamptz NOT NULL,
    expires_at   timestamptz,
    revoked_at   timestamptz,
    CHECK (expires_at IS NULL OR expires_at > created_at)
);
CREATE TRIGGER api_keys_created_at BEFORE UPDATE ON api_keys
    FOR EACH ROW EXECUTE FUNCTION forbid_created_at_change();
CREATE INDEX api_keys_tenant_kind ON api_keys (tenant_id, kind, id);
CREATE INDEX api_keys_tenant_user ON api_keys (tenant_id, user_id, kind, id);

-- Platform audit records. Retained 30 days from creation, independent of key validity.
CREATE TABLE audit_records (
    id         uuid PRIMARY KEY,
    -- operator:<sha256 of issuer and subject>. Never a raw subject, email or token.
    actor      text NOT NULL CHECK (octet_length(actor) BETWEEN 1 AND 128),
    action     text NOT NULL CHECK (action <> ''),
    -- Mandatory for mutations; empty only for read-only inspection.
    reason     text NOT NULL CHECK (octet_length(reason) <= 1000),
    request_id uuid NOT NULL,
    tenant_id  uuid,
    target_id  uuid,
    -- Safe metadata only: changed setting names and values, never content or secrets.
    details    jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(details) = 'object'),
    created_at timestamptz NOT NULL
);
CREATE TRIGGER audit_records_created_at BEFORE UPDATE ON audit_records
    FOR EACH ROW EXECUTE FUNCTION forbid_created_at_change();
CREATE INDEX audit_records_created ON audit_records (created_at);

-- Safe operational event categories and correlation IDs. Retained 30 days from creation.
CREATE TABLE operational_events (
    id             uuid PRIMARY KEY,
    category       text NOT NULL CHECK (category <> ''),
    severity       text NOT NULL CHECK (severity IN ('info', 'warn', 'error')),
    request_id     uuid,
    correlation_id uuid NOT NULL,
    details        jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(details) = 'object'),
    created_at     timestamptz NOT NULL
);
CREATE TRIGGER operational_events_created_at BEFORE UPDATE ON operational_events
    FOR EACH ROW EXECUTE FUNCTION forbid_created_at_change();
CREATE INDEX operational_events_created ON operational_events (created_at);
